CREATE TABLE IF NOT EXISTS "procurement_item" ("id" serial PRIMARY KEY, "item_name" text NOT NULL, "price" numeric(12,2) NOT NULL DEFAULT 0, "quantity" integer NOT NULL DEFAULT 1, "platform" text, "link" text, "screenshot" text, "requester" text, "anchor_name" text, "room" text, "usage" text, "remarks" text, "invoice" text DEFAULT '可开票', "status" text NOT NULL DEFAULT 'pending_approval', "order_id" text, "tracking_no" text, "shop_name" text, "actual_price" numeric(12,2), "return_reason" text, "refund_amount" numeric(12,2) DEFAULT 0, "submitter_user_id" text, "submitter" text, "submitter_team_id" text, "approver_user_id" text, "approver_name" text, "approval_remark" text, "approval_date" date, "submission_date" date, "purchase_date" date, "received_date" date, "return_date" date, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "procurement_log" ("id" serial PRIMARY KEY, "item_id" integer NOT NULL REFERENCES "procurement_item"("id") ON DELETE CASCADE, "action" text NOT NULL, "from_status" text, "to_status" text, "operator_user_id" text, "operator" text, "remark" text, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "idx_procurement_item_status" ON "procurement_item" ("status"); CREATE INDEX IF NOT EXISTS "idx_procurement_log_item" ON "procurement_log" ("item_id");
CREATE TABLE IF NOT EXISTS "attendance_record" ("id" serial PRIMARY KEY, "dingtalk_user_id" text NOT NULL, "name" text NOT NULL, "dept_name" text NOT NULL DEFAULT '', "work_date" date NOT NULL, "on_duty_time" timestamptz, "off_duty_time" timestamptz, "on_duty_result" text, "off_duty_result" text, "on_duty_location" text, "off_duty_location" text, "all_check_times" jsonb NOT NULL DEFAULT '[]', "late_minutes" integer NOT NULL DEFAULT 0, "early_leave_minutes" integer NOT NULL DEFAULT 0, "work_duration" text, "absent_days" numeric(5,2) NOT NULL DEFAULT 0, "attendance_days" numeric(5,2) NOT NULL DEFAULT 0, "rest_days" numeric(5,2) NOT NULL DEFAULT 0, "remark" text, "remark_by" text, "remark_at" timestamptz, "verified_by" text, "verified_at" timestamptz, "raw_data" jsonb, "synced_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "uq_attendance_record_user_date" UNIQUE ("dingtalk_user_id", "work_date"));
CREATE TABLE IF NOT EXISTS "attendance_sync_log" ("id" serial PRIMARY KEY, "sync_date" date NOT NULL, "total" integer NOT NULL DEFAULT 0, "synced" integer NOT NULL DEFAULT 0, "failed" integer NOT NULL DEFAULT 0, "skipped" integer NOT NULL DEFAULT 0, "triggered_by" text NOT NULL DEFAULT 'manual', "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "attendance_approval" ("id" serial PRIMARY KEY, "instance_id" text NOT NULL UNIQUE, "process_code" text NOT NULL, "approval_type" text NOT NULL, "title" text, "originator_user_id" text NOT NULL, "originator_name" text, "dept_name" text, "status" text NOT NULL, "result" text, "start_time" timestamptz, "end_time" timestamptz, "duration_hours" numeric(8,2), "reason" text, "leave_type" text, "form_data" jsonb, "create_time" timestamptz, "finish_time" timestamptz, "synced_at" timestamptz);
INSERT INTO "role_default_permission" (position,module,scope,points,description,updated_at)
SELECT p.position,'procurement',CASE WHEN p.position IN ('总监','老板') THEN 'all' ELSE 'self' END,
  CASE WHEN p.position IN ('总监','老板') THEN '["create","approve","manage","export"]'::jsonb ELSE '["create"]'::jsonb END,'道具采购',now()
FROM (SELECT DISTINCT position FROM "role_default_permission") p ON CONFLICT (position,module) DO NOTHING;
INSERT INTO "role_default_permission" (position,module,scope,points,description,updated_at)
SELECT p.position,'attendance',CASE WHEN p.position IN ('总监','老板') THEN 'all' ELSE 'self' END,
  CASE WHEN p.position IN ('总监','老板') THEN '["sync","remark","approval","export"]'::jsonb ELSE '["remark","approval"]'::jsonb END,'考勤打卡',now()
FROM (SELECT DISTINCT position FROM "role_default_permission") p ON CONFLICT (position,module) DO NOTHING;
